import{H as e,_t as t,it as n,rt as r}from"./chunks/framework.CNIcw2kk.js";var i=JSON.parse(`{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md","lastUpdated":1785475484000}`),a={name:`guide/troubleshooting.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h1><p>Symptoms seen in practice, and what each one actually means.</p><h2 id="exit-codes" tabindex="-1">Exit codes <a class="header-anchor" href="#exit-codes" aria-label="Permalink to “Exit codes”">​</a></h2><h3 id="is-0-but-the-output-says-files-failed" tabindex="-1"><code>$?</code> is 0 but the output says files failed <a class="header-anchor" href="#is-0-but-the-output-says-files-failed" aria-label="Permalink to “$? is 0 but the output says files failed”">​</a></h3><p>The exit code came from the last command in a pipeline, not from comply.</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comply</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> $?</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">     # reports tail&#39;s status -- always 0</span></span></code></pre></div><p>Capture the output, or test the command directly:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comply</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> report.txt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$?</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comply</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --quiet</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compliant</span></span></code></pre></div><p>This bites <code>format --check</code> most often, whose entire purpose is the exit code.</p><h2 id="lint-results" tabindex="-1">Lint results <a class="header-anchor" href="#lint-results" aria-label="Permalink to “Lint results”">​</a></h2><h3 id="missing-licenses-mit-apache-2-0-right-after-comply-init" tabindex="-1"><code>Missing licenses: MIT, Apache-2.0</code> right after <code>comply init</code> <a class="header-anchor" href="#missing-licenses-mit-apache-2-0-right-after-comply-init" aria-label="Permalink to “Missing licenses: MIT, Apache-2.0 right after comply init”">​</a></h3><p><code>init</code> writes the manifest but does not populate <code>LICENSES/</code>. Every licence a project references needs a text file there.</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comply</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> download</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all</span></span></code></pre></div><p><code>--all</code> fetches exactly what <code>lint</code> reported missing.</p><h3 id="unused-licenses-id" tabindex="-1"><code>Unused licenses: &lt;ID&gt;</code> <a class="header-anchor" href="#unused-licenses-id" aria-label="Permalink to “Unused licenses: &lt;ID&gt;”">​</a></h3><p>A file exists in <code>LICENSES/</code> that nothing declares. Either something should be using it, or the text is left over from a licence you have dropped.</p><p>A licence declared only through an annotation still counts as used, including for a file listed in <code>[tool.comply] ignore</code> -- comply reads the annotation covering it. If a licence still reports unused, nothing in the manifest names it.</p><h3 id="a-file-is-reported-as-skipped-not-checked" tabindex="-1">A file is reported as <code>skipped</code>, not checked <a class="header-anchor" href="#a-file-is-reported-as-skipped-not-checked" aria-label="Permalink to “A file is reported as skipped, not checked”">​</a></h3><p>It is outside REUSE analysis. That is one of:</p><ul><li>a licence text (<code>LICENSES/</code>, root <code>LICENSE*</code> files),</li><li>the manifest itself,</li><li>an SPDX document,</li><li>a <code>.license</code> companion, judged through the file it describes,</li><li>a path matched by <code>[tool.comply] ignore</code>,</li><li>a symlink -- never followed, because the target is covered in its own right.</li></ul><p>Skipped files are counted in the total but require nothing.</p><h3 id="lint-file-passes-a-file-with-no-header" tabindex="-1"><code>lint-file</code> passes a file with no header <a class="header-anchor" href="#lint-file-passes-a-file-with-no-header" aria-label="Permalink to “lint-file passes a file with no header”">​</a></h3><p>Correct, if <code>REUSE.toml</code> covers it. An aggregate annotation is a real declaration; requiring a header as well would defeat the point of having one.</p><h3 id="lint-finds-problems-lint-file-did-not" tabindex="-1"><code>lint</code> finds problems <code>lint-file</code> did not <a class="header-anchor" href="#lint-finds-problems-lint-file-did-not" aria-label="Permalink to “lint finds problems lint-file did not”">​</a></h3><p>By design. Unused licences and missing licence texts are project-wide findings that need the whole tree. Run <code>lint-file</code> in a pre-commit hook and <code>lint</code> in CI.</p><h2 id="annotating" tabindex="-1">Annotating <a class="header-anchor" href="#annotating" aria-label="Permalink to “Annotating”">​</a></h2><h3 id="the-copyright-year-appears-twice" tabindex="-1">The copyright year appears twice <a class="header-anchor" href="#the-copyright-year-appears-twice" aria-label="Permalink to “The copyright year appears twice”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// SPDX-FileCopyrightText: 2026 2026 Acme</span></span></code></pre></div><p>comply prepends a year to <code>--copyright</code> unconditionally, so a value that already carries one is doubled. Pass a bare name:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comply</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> annotate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --license</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MIT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --copyright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Acme&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --year</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2026</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> file.rs</span></span></code></pre></div><p><code>reuse</code> behaves identically, so this is a compatibility choice rather than a bug. <code>--exclude-year</code> strips the year back off. See <a href="/comply/docs/reference/cli#the-year-is-added-for-you">The year is added for you</a>.</p><h3 id="the-notice-is-written-with-the-wrong-marker" tabindex="-1">The notice is written with the wrong marker <a class="header-anchor" href="#the-notice-is-written-with-the-wrong-marker" aria-label="Permalink to “The notice is written with the wrong marker”">​</a></h3><p><code>--copyright-prefix</code> chooses among the sixteen forms the specification allows:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comply</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> annotate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --license</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MIT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --copyright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Acme</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --copyright-prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> string-c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> file.rs</span></span></code></pre></div><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// Copyright (C) 2026 Acme</span></span></code></pre></div><p>The full table is in <a href="/comply/docs/reference/cli#copyright-forms">Copyright forms</a>. The prefix applies to the header only -- with <code>--update-reuse-toml</code>, the annotation keeps the bare notice.</p><h3 id="annotate-reports-success-but-the-file-is-unchanged" tabindex="-1"><code>annotate</code> reports success but the file is unchanged <a class="header-anchor" href="#annotate-reports-success-but-the-file-is-unchanged" aria-label="Permalink to “annotate reports success but the file is unchanged”">​</a></h3><p>The file already had a header. Without <code>--force</code>, comply keeps it rather than overwriting a declaration someone made deliberately.</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comply</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> annotate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --license</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MIT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --copyright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Acme</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> file.rs</span></span></code></pre></div><p>This is also why <code>--merge-copyrights</code> can look inert -- it has nothing to rewrite until <code>--force</code> lets it.</p><h3 id="a-licence-text-got-overwritten-with-an-spdx-header" tabindex="-1">A licence text got overwritten with an SPDX header <a class="header-anchor" href="#a-licence-text-got-overwritten-with-an-spdx-header" aria-label="Permalink to “A licence text got overwritten with an SPDX header”">​</a></h3><p><code>annotate</code> was pointed at a symlink. Writing through a link edits its target, so annotating a root <code>LICENSE-MIT</code> that points into <code>LICENSES/</code> rewrites the canonical text.</p><p>Recover with git, then add the path to <code>[tool.comply] ignore</code>:</p><div class="language-toml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comply</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ignore = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;LICENSE-*&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;crates/*/LICENSE-*&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p><code>--recursive</code> over a directory holding such links is the usual way this happens.</p><h3 id="a-toml-or-markdown-file-was-mangled" tabindex="-1">A TOML or Markdown file was mangled <a class="header-anchor" href="#a-toml-or-markdown-file-was-mangled" aria-label="Permalink to “A TOML or Markdown file was mangled”">​</a></h3><p>Older versions treated any line carrying an SPDX tag as a header, including tags inside a string literal or a fenced code block, and rewrote around them. comply now requires a header to be <em>in a comment</em>.</p><p>If a file legitimately contains SPDX-shaped text that must not be touched, guard it:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>REUSE-IgnoreStart</span></span>
<span class="line"><span>... text containing SPDX tags ...</span></span>
<span class="line"><span>REUSE-IgnoreEnd</span></span></code></pre></div><p>Do not nest those guards. An inner <code>REUSE-IgnoreEnd</code> closes the outer block and silently unguards the remainder of the file.</p><h3 id="a-header-landed-above-the-shebang" tabindex="-1">A header landed above the shebang <a class="header-anchor" href="#a-header-landed-above-the-shebang" aria-label="Permalink to “A header landed above the shebang”">​</a></h3><p>Fixed. Headers are inserted below a shebang or YAML frontmatter, because prepending there stops the kernel finding the interpreter and turns frontmatter into a setext heading.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h2><h3 id="a-tool-comply-comment-styles-rule-is-refused" tabindex="-1">A <code>[[tool.comply.comment-styles]]</code> rule is refused <a class="header-anchor" href="#a-tool-comply-comment-styles-rule-is-refused" aria-label="Permalink to “A [[tool.comply.comment-styles]] rule is refused”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Error: two [[tool.comply.comment-styles]] rules claim the extension \`vue\`;</span></span>
<span class="line"><span>remove one, or lookup order would silently decide</span></span></code></pre></div><p>Two rules claim the same key. This is refused at parse time rather than resolved by position, so the order of the table never becomes an invisible precedence rule. Extensions compare case-insensitively; filenames compare exactly.</p><h3 id="a-configured-comment-style-is-written-but-not-recognised-on-the-next-run" tabindex="-1">A configured comment style is written but not recognised on the next run <a class="header-anchor" href="#a-configured-comment-style-is-written-but-not-recognised-on-the-next-run" aria-label="Permalink to “A configured comment style is written but not recognised on the next run”">​</a></h3><p>That was a defect where a style comply wrote was not matched on the way back in, so a second run stacked a second header. Fixed: rendering, comment detection, tag stripping and span detection all derive from the same rule table.</p><p>If you still see it, check the rule declares the same delimiters the file actually uses -- a <code>close</code> that does not match means comply sees a line style where the file has a block.</p><h3 id="files-under-an-ignored-directory-still-appear" tabindex="-1">Files under an ignored directory still appear <a class="header-anchor" href="#files-under-an-ignored-directory-still-appear" aria-label="Permalink to “Files under an ignored directory still appear”">​</a></h3><p><code>ignore</code> takes globs, so a directory needs <code>dir/**</code> rather than <code>dir</code>.</p><h2 id="environment" tabindex="-1">Environment <a class="header-anchor" href="#environment" aria-label="Permalink to “Environment”">​</a></h2><h3 id="could-not-run-curl-install-it-or-pass-source-with-a-local-path" tabindex="-1"><code>could not run curl; install it or pass --source with a local path</code> <a class="header-anchor" href="#could-not-run-curl-install-it-or-pass-source-with-a-local-path" aria-label="Permalink to “could not run curl; install it or pass --source with a local path”">​</a></h3><p><code>download</code> shells out to <code>curl</code>, which is not on <code>PATH</code>. Either install it, or avoid the network entirely:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comply</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> download</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./licence-cache/{}.txt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MIT</span></span></code></pre></div><p>This also appears in containers: an image that runs comply&#39;s test suite needs <code>curl</code>, and a minimal base image will not have it.</p><h3 id="results-differ-between-a-workstation-and-ci" tabindex="-1">Results differ between a workstation and CI <a class="header-anchor" href="#results-differ-between-a-workstation-and-ci" aria-label="Permalink to “Results differ between a workstation and CI”">​</a></h3><p>Two usual causes.</p><p><strong>Coverage attribution.</strong> tarpaulin attributes closure and const-fn bodies differently per platform, so a macOS run can report a different figure from the Linux run CI uses -- and the difference is not always in your favour: a tree CI measured at 99.77% reported 100% locally. There is no local reproduction any more; <code>mise run docker:test</code> claimed to be one and was not, reporting green on the exact tree CI failed, so it was removed rather than left to be trusted. Reproduce with <code>act -W .github/workflows/tests/act-ci.yml</code>, which does agree with CI.</p><p><strong>gitignore state.</strong> comply honours gitignore rules but never drops a file git tracks, since git does not apply those rules to tracked files either. A file ignored locally but committed is still checked.</p>`,70)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};